mod account {
    pub struct User {
        name: Str,
        pub email: Str,
    }

    pub fn create(name: Str, email: Str) -> User {
        return User { name, email }
    }

    pub fn greet(user: &User) {
        io.println("Hello, {user.name}!")
    }
}

fn main() {
    let u = account::create("Ada", "ada@axiom.dev")
    account::greet(&u)
    io.println("Email: {u.email}")
}
